const listWorkspaceHelpCenterSubdomains = `-- name: ListWorkspaceHelpCenterSubdomains :many
SELECT subdomain FROM help_centers WHERE workspace_id = $1 AND deleted_at IS NULL AND status = 'active'
`

// ListWorkspaceHelpCenterSubdomains lists the subdomains of the
// workspace's live help centers.
func (q *Queries) ListWorkspaceHelpCenterSubdomains(ctx context.Context, workspaceID ids.UUID) ([]string, error) {
	rows, err := q.db.Query(ctx, listWorkspaceHelpCenterSubdomains, workspaceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var subdomain string
		if err := rows.Scan(&subdomain); err != nil {
			return nil, err
		}
		items = append(items, subdomain)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

