const searchPublishedArticles = `-- name: SearchPublishedArticles :many
SELECT a.id, a.collection_id, v.title, v.slug, v.description, v.body_markdown, v.visibility,
    ts_rank_cd(v.search_document, query)::real AS rank,
    ts_headline('dimmi_search', v.body_markdown, query,
        'MaxWords=30, MinWords=12, ShortWord=2, MaxFragments=1, StartSel=<mark>, StopSel=</mark>')::text AS snippet
FROM articles a
JOIN article_versions v ON v.id = a.published_version_id,
    websearch_to_tsquery('dimmi_search', $1::text) AS query
WHERE a.workspace_id = $2 AND a.help_center_id = $3 AND a.deleted_at IS NULL
  AND a.status = 'published' AND v.search_document @@ query
  AND (v.visibility = 'public' OR $4::boolean)
ORDER BY rank DESC, a.id
LIMIT $5
`

type SearchPublishedArticlesParams struct {
	Query            string   `json:"query"`
	WorkspaceID      ids.UUID `json:"workspace_id"`
	HelpCenterID     ids.UUID `json:"help_center_id"`
	IncludeAgentOnly bool     `json:"include_agent_only"`
	RowLimit         int32    `json:"row_limit"`
}

type SearchPublishedArticlesRow struct {
	ID           ids.UUID  `json:"id"`
	CollectionID *ids.UUID `json:"collection_id"`
	Title        string    `json:"title"`
	Slug         string    `json:"slug"`
	Description  *string   `json:"description"`
	BodyMarkdown string    `json:"body_markdown"`
	Visibility   string    `json:"visibility"`
	Rank         float32   `json:"rank"`
	Snippet      string    `json:"snippet"`
}

// SearchPublishedArticles finds published articles matching a query,
// best first, public ones only unless agent-only ones are asked for.
func (q *Queries) SearchPublishedArticles(ctx context.Context, arg SearchPublishedArticlesParams) ([]SearchPublishedArticlesRow, error) {
	rows, err := q.db.Query(ctx, searchPublishedArticles,
		arg.Query,
		arg.WorkspaceID,
		arg.HelpCenterID,
		arg.IncludeAgentOnly,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SearchPublishedArticlesRow
	for rows.Next() {
		var i SearchPublishedArticlesRow
		if err := rows.Scan(
			&i.ID,
			&i.CollectionID,
			&i.Title,
			&i.Slug,
			&i.Description,
			&i.BodyMarkdown,
			&i.Visibility,
			&i.Rank,
			&i.Snippet,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

