const upsertRedirect = `-- name: UpsertRedirect :exec
INSERT INTO help_center_redirects (
    workspace_id, help_center_id, from_path, target_type, target_article_id, target_collection_id, source,
    created_at, updated_at
) VALUES (
    $1, $2, $3, $4, $5, $6, $7,
    $8, $8
)
ON CONFLICT (help_center_id, from_path) DO UPDATE SET
    target_type = excluded.target_type, target_article_id = excluded.target_article_id,
    target_collection_id = excluded.target_collection_id, target_url = NULL, source = excluded.source,
    updated_at = excluded.updated_at
`

type UpsertRedirectParams struct {
	WorkspaceID        ids.UUID  `json:"workspace_id"`
	HelpCenterID       ids.UUID  `json:"help_center_id"`
	FromPath           string    `json:"from_path"`
	TargetType         string    `json:"target_type"`
	TargetArticleID    *ids.UUID `json:"target_article_id"`
	TargetCollectionID *ids.UUID `json:"target_collection_id"`
	Source             string    `json:"source"`
	Now                time.Time `json:"now"`
}

// UpsertRedirect points an old path at its new target.
func (q *Queries) UpsertRedirect(ctx context.Context, arg UpsertRedirectParams) error {
	_, err := q.db.Exec(ctx, upsertRedirect,
		arg.WorkspaceID,
		arg.HelpCenterID,
		arg.FromPath,
		arg.TargetType,
		arg.TargetArticleID,
		arg.TargetCollectionID,
		arg.Source,
		arg.Now,
	)
	return err
}
